'use strict';
(()=>{
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const number=n=>n===null||n===undefined?'Unavailable':Number(n).toLocaleString();
 const labels={1:'24 hours',7:'7 days',30:'30 days',180:'6 months',365:'365 days'};
 function comparison(current,previous,complete=true){if(!complete||current===null||previous===null||previous===undefined)return 'Previous period unavailable';const delta=current-previous;if(!previous)return current?'New activity; previous period was zero':'No change';return `${delta>0?'+':''}${Math.round(delta/previous*100).toLocaleString()}% vs previous period (${number(previous)})`}
 const metric=(n,label,note)=>`<div class="metric"><strong>${number(n)}</strong><span>${esc(label)}</span><small class="metric-note">${esc(note)}</small></div>`;
 const setup='<p class="analytics-caption" role="status">Apply <a href="https://github.com/sparx1981/RepoShelf/blob/main/supabase/migrations/202610090028_admin_analytics_overview.sql" target="_blank" rel="noopener noreferrer">migration 28</a> in Supabase to enable Overview, period comparisons, search terms and country reporting.</p>';
 function traffic(d,fallback){if(!d?.configured){const total=k=>(fallback?.daily||[]).reduce((n,r)=>n+Number(r[k]||0),0);return setup+(fallback?'<section class="analytics-group"><h3>Traffic</h3><div class="metric-grid">'+metric(fallback.uniqueVisitors,'Unique visitors','Comparison awaiting migration 28')+metric(total('visits'),'Visits','')+metric(total('page_views'),'Page views','')+metric(total('listing_views'),'Listing views','')+'</div></section><section class="analytics-group"><h3>Engagement</h3><div class="metric-grid">'+metric(total('demo_clicks'),'Demo clicks','')+metric(total('fork_clicks'),'Fork / duplicate clicks','')+metric(total('searches'),'Searches','')+'</div></section>':'');}const cur=d.current,prev=d.previous,card=(key,label)=>metric(cur[key],label,comparison(cur[key],prev[key],prev.complete));return `<section class="analytics-group"><h3>Traffic</h3><div class="metric-grid">${card('uniqueVisitors','Unique visitors')}${card('visits','Visits')}${card('page_views','Page views')}${card('listing_views','Listing views')}</div></section><section class="analytics-group"><h3>Engagement</h3><div class="metric-grid">${card('demo_clicks','Demo clicks')}${card('fork_clicks','Fork / duplicate clicks')}${card('searches','Searches')}</div></section><p class="analytics-caption">${cur.complete?'':'Selected period has partial history. '}24 hours uses rolling timestamps. Longer ranges use UTC dates including today; 6 months is 180 days. Cross-day unique visitors are unavailable beyond detailed event retention (90 days); daily visitor totals remain available in Overview. Comparisons use the preceding equal-length period.</p>`}
 function aggregateTables(d){if(!d?.configured)return '';let countries;try{countries=new Intl.DisplayNames(undefined,{type:'region'})}catch{};const table=(heading,columns,rows)=>`<section class="analytics-box"><h3>${heading}</h3>${rows.length?`<div class="help-table-wrap"><table class="analytics-table"><thead><tr>${columns.map(c=>`<th scope="col">${c}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:'<p class="chart-empty">No reportable activity yet. Totals appear after at least three matching searches or page views.</p>'}</section>`;return `<div class="analytics-grid">${table('Popular search terms',['Term','Source','Searches'],(d.searchTerms||[]).map(r=>`<tr><td>${esc(r.term)}</td><td>${r.source==='mcp'?'AI connector':'Website'}</td><td class="num">${number(r.searches)}</td></tr>`))}${table('Visitor countries',['Country','Page views'],(d.countries||[]).map(r=>`<tr><td>${esc(countries?.of(r.country)||r.country)}</td><td class="num">${number(r.page_views)}</td></tr>`))}</div><p class="analytics-caption">New reporting starts after migration 28 and renewed website analytics consent. No account or browser links are retained with terms. Countries count consented page views with an available country code; no IP addresses are stored. 24-hour totals use minute buckets; longer ranges use UTC dates.</p>`}
 function overview(d){if(!d?.configured)return setup;const rows=d.periods||[],growth=new Map((d.catalogueGrowth||[]).map(r=>[r.days,r]));const table=(name,heading,fn)=>`<section class="analytics-box"><h3>${name}</h3><div class="help-table-wrap"><table class="analytics-table overview-table"><thead><tr><th scope="col">Period</th><th scope="col">${heading}</th><th scope="col">Compared with preceding period</th></tr></thead><tbody>${rows.map(r=>{const v=fn(r);return `<tr><th scope="row">${labels[r.days]}</th><td class="num">${number(v.current)}</td><td>${esc(comparison(v.current,v.previous,v.complete))}</td></tr>`}).join('')}</tbody></table></div></section>`;
 const ops=d.operations||{},stamp=at=>at?`<time datetime="${esc(at)}">${esc(new Date(at).toLocaleString())}</time>`:'Unavailable';
 return `<div class="metric-grid">${metric(d.users,'Signed-up users','Current accounts; deleted or merged accounts are excluded')}${metric(rows[0]?.current?.visitors,'Visitors in 24 hours','Unique per UTC day; a browser can count on both days')}${metric(rows[0]?.current?.demo_clicks,'Demo clicks in 24 hours','Consented visitor activity')}${metric(d.publicCount,'Public catalogue','Eligible listings after current administrator restrictions')}</div><div class="analytics-grid">${table('User growth','New accounts',r=>({current:r.signups,previous:r.previousSignups,complete:true}))}${table('Visitors','Daily unique visitors',r=>({current:r.current.visitors,previous:r.previous.visitors,complete:r.previous.complete}))}${table('Demo clicks','Clicks',r=>({current:r.current.demo_clicks,previous:r.previous.demo_clicks,complete:r.previous.complete}))}${table('Public catalogue growth','Net change',r=>({...growth.get(r.days),complete:growth.get(r.days)?.previous!==null}))}</div><p class="analytics-caption">6 months means 180 days. Visitors are counted once per UTC day, then summed across the period. Missing historical baselines are unavailable. Catalogue growth uses saved publication-eligible snapshots; past administrator restrictions cannot be reconstructed.${d.catalogueSummaryAt?' Catalogue snapshot: '+esc(new Date(d.catalogueSummaryAt).toLocaleString())+'.':''}</p><section class="analytics-box"><h3>Sync and publication</h3><dl class="overview-operations"><div><dt>Last completed sync</dt><dd>${stamp(ops.lastSyncAt)} <small data-overview-clock="${esc(ops.lastSyncAt||'')}" data-clock-mode="ago"></small></dd><dd>Public catalogue change in this sync: ${number(ops.lastSyncGrowth)}</dd></div><div><dt>Next scheduled sync</dt><dd>${stamp(ops.nextSyncAt)} <small data-overview-clock="${esc(ops.nextSyncAt||'')}" data-clock-mode="next"></small></dd><dd>Scheduled time; GitHub may start later.</dd></div><div><dt>Last catalogue publication</dt><dd>${stamp(ops.publication?.lastPublishedAt)}</dd><dd>Recorded publication; deployment can follow shortly afterwards.</dd></div></dl></section><div class="overview-links"><button class="button outline" data-admin-tab="analytics">Detailed analytics</button><button class="button outline" data-admin-tab="users">Manage users</button><button class="button outline" data-admin-tab="sync">Sync log</button></div>`;
 }
 const api={comparison,traffic,aggregateTables,overview};if(typeof module==='object'&&module.exports)module.exports=api;else window.RepoAdminOverview=api;
})();
